/// Looks up the flattened width table for a standard-14 base font name and
/// PDF /Encoding name. Returns None for non-standard (embedded/subset) fonts,
/// which must supply their own /Widths or /W array instead.
pub fn standard_font_table(base_font: &str, encoding: &str) -> Option<&'static [u16; 256]> {
    let enc_key = if encoding == "WinAnsiEncoding" { "WinAnsiEncoding" } else { "StandardEncoding" };
    match (base_font, enc_key) {
        ("Courier", "StandardEncoding") => Some(&COURIER_STANDARDENCODING),
        ("Courier-Bold", "StandardEncoding") => Some(&COURIER_BOLD_STANDARDENCODING),
        ("Courier-BoldOblique", "StandardEncoding") => Some(&COURIER_BOLDOBLIQUE_STANDARDENCODING),
        ("Courier-Oblique", "StandardEncoding") => Some(&COURIER_OBLIQUE_STANDARDENCODING),
        ("Helvetica", "StandardEncoding") => Some(&HELVETICA_STANDARDENCODING),
        ("Helvetica-Bold", "StandardEncoding") => Some(&HELVETICA_BOLD_STANDARDENCODING),
        ("Helvetica-BoldOblique", "StandardEncoding") => Some(&HELVETICA_BOLDOBLIQUE_STANDARDENCODING),
        ("Helvetica-Oblique", "StandardEncoding") => Some(&HELVETICA_OBLIQUE_STANDARDENCODING),
        ("Times-Roman", "StandardEncoding") => Some(&TIMES_ROMAN_STANDARDENCODING),
        ("Times-Bold", "StandardEncoding") => Some(&TIMES_BOLD_STANDARDENCODING),
        ("Times-BoldItalic", "StandardEncoding") => Some(&TIMES_BOLDITALIC_STANDARDENCODING),
        ("Times-Italic", "StandardEncoding") => Some(&TIMES_ITALIC_STANDARDENCODING),
        ("Courier", "WinAnsiEncoding") => Some(&COURIER_WINANSIENCODING),
        ("Courier-Bold", "WinAnsiEncoding") => Some(&COURIER_BOLD_WINANSIENCODING),
        ("Courier-BoldOblique", "WinAnsiEncoding") => Some(&COURIER_BOLDOBLIQUE_WINANSIENCODING),
        ("Courier-Oblique", "WinAnsiEncoding") => Some(&COURIER_OBLIQUE_WINANSIENCODING),
        ("Helvetica", "WinAnsiEncoding") => Some(&HELVETICA_WINANSIENCODING),
        ("Helvetica-Bold", "WinAnsiEncoding") => Some(&HELVETICA_BOLD_WINANSIENCODING),
        ("Helvetica-BoldOblique", "WinAnsiEncoding") => Some(&HELVETICA_BOLDOBLIQUE_WINANSIENCODING),
        ("Helvetica-Oblique", "WinAnsiEncoding") => Some(&HELVETICA_OBLIQUE_WINANSIENCODING),
        ("Times-Roman", "WinAnsiEncoding") => Some(&TIMES_ROMAN_WINANSIENCODING),
        ("Times-Bold", "WinAnsiEncoding") => Some(&TIMES_BOLD_WINANSIENCODING),
        ("Times-BoldItalic", "WinAnsiEncoding") => Some(&TIMES_BOLDITALIC_WINANSIENCODING),
        ("Times-Italic", "WinAnsiEncoding") => Some(&TIMES_ITALIC_WINANSIENCODING),
        _ => None,
    }
}

/// A handful of very common non-standard-but-metrically-equivalent BaseFont
/// names (Arial has never needed its own AFM file precisely because it was
/// designed to be width-compatible with Helvetica; same story for the other
/// two families below).
pub fn normalize_base_font_name(name: &str) -> &str {
    match name {
        "Arial" => "Helvetica",
        "Arial,Bold" | "Arial-Bold" | "Arial-BoldMT" => "Helvetica-Bold",
        "Arial,Italic" | "Arial-Italic" | "Arial-ItalicMT" => "Helvetica-Oblique",
        "Arial,BoldItalic" | "Arial-BoldItalicMT" => "Helvetica-BoldOblique",
        "TimesNewRoman" | "TimesNewRomanPSMT" => "Times-Roman",
        "TimesNewRoman,Bold" | "TimesNewRomanPS-BoldMT" => "Times-Bold",
        "TimesNewRoman,Italic" | "TimesNewRomanPS-ItalicMT" => "Times-Italic",
        "TimesNewRoman,BoldItalic" | "TimesNewRomanPS-BoldItalicMT" => "Times-BoldItalic",
        "CourierNew" | "CourierNewPSMT" => "Courier",
        "CourierNew,Bold" | "CourierNewPS-BoldMT" => "Courier-Bold",
        other => other,
    }
}
